api_client = '''import axios, { AxiosResponse } from 'axios';

// API Configuration
const HF_SPACES_API = process.env.NEXT_PUBLIC_HF_SPACES_API || 'https://oasis-v3-hf.hf.space';
const TERMUX_ORCHESTRATOR_API = process.env.NEXT_PUBLIC_TERMUX_API || 'http://localhost:8000';

// API Client Configuration
const hfSpacesClient = axios.create({
  baseURL: HF_SPACES_API,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
    'X-Client': 'OASIS-v3-Frontend',
  },
});

const termuxClient = axios.create({
  baseURL: TERMUX_ORCHESTRATOR_API,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
    'X-Client': 'OASIS-v3-Frontend',
  },
});

// Request/Response Types
export interface AIProcessingRequest {
  model_type: 'text' | 'image' | 'audio' | 'multimodal';
  input: string | File;
  parameters?: Record<string, any>;
  stream?: boolean;
}

export interface AIProcessingResponse {
  result: any;
  processing_time: number;
  model_used: string;
  cost: number;
  request_id: string;
  timestamp: string;
}

export interface RevenueMetrics {
  total_revenue: number;
  requests_today: number;
  requests_month: number;
  average_cost_per_request: number;
  top_models: Array<{
    model: string;
    requests: number;
    revenue: number;
  }>;
}

export interface TermuxStatus {
  status: 'online' | 'offline' | 'connecting';
  latency: number;
  memory_usage: number;
  active_connections: number;
  last_heartbeat: string;
}

// API Service Class
export class OASISAPIClient {

  // Text Processing
  async processText(
    prompt: string, 
    model?: string, 
    parameters?: Record<string, any>
  ): Promise<AIProcessingResponse> {
    try {
      const response: AxiosResponse<AIProcessingResponse> = await hfSpacesClient.post('/api/v1/text/generate', {
        model_type: 'text',
        input: prompt,
        model: model || 'default',
        parameters: parameters || {},
      });

      return response.data;
    } catch (error) {
      console.error('Text processing error:', error);
      throw new Error('Failed to process text request');
    }
  }

  // Image Processing
  async processImage(
    imageFile: File,
    task: 'caption' | 'classify' | 'generate' | 'edit',
    parameters?: Record<string, any>
  ): Promise<AIProcessingResponse> {
    try {
      const formData = new FormData();
      formData.append('image', imageFile);
      formData.append('task', task);
      if (parameters) {
        formData.append('parameters', JSON.stringify(parameters));
      }

      const response: AxiosResponse<AIProcessingResponse> = await hfSpacesClient.post('/api/v1/image/process', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      return response.data;
    } catch (error) {
      console.error('Image processing error:', error);
      throw new Error('Failed to process image request');
    }
  }

  // Audio Processing
  async processAudio(
    audioFile: File,
    task: 'transcribe' | 'translate' | 'classify',
    parameters?: Record<string, any>
  ): Promise<AIProcessingResponse> {
    try {
      const formData = new FormData();
      formData.append('audio', audioFile);
      formData.append('task', task);
      if (parameters) {
        formData.append('parameters', JSON.stringify(parameters));
      }

      const response: AxiosResponse<AIProcessingResponse> = await hfSpacesClient.post('/api/v1/audio/process', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      return response.data;
    } catch (error) {
      console.error('Audio processing error:', error);
      throw new Error('Failed to process audio request');
    }
  }

  // Streaming Text Generation (for real-time responses)
  async streamText(
    prompt: string,
    model?: string,
    onToken?: (token: string) => void,
    onComplete?: (response: AIProcessingResponse) => void
  ): Promise<void> {
    try {
      const response = await fetch(`${HF_SPACES_API}/api/v1/text/stream`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Client': 'OASIS-v3-Frontend',
        },
        body: JSON.stringify({
          input: prompt,
          model: model || 'default',
          stream: true,
        }),
      });

      if (!response.body) {
        throw new Error('No response body for streaming');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();

        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));
              if (data.token && onToken) {
                onToken(data.token);
              }
              if (data.complete && onComplete) {
                onComplete(data.response);
              }
            } catch (e) {
              // Ignore malformed JSON
            }
          }
        }
      }
    } catch (error) {
      console.error('Streaming error:', error);
      throw new Error('Failed to stream text generation');
    }
  }

